export const fetchPhotos = async (page, limit) => {
  const apiUrl = `https://picsum.photos/v2/list?limit=${limit}&page=${page}`;

  try {
    const data = await fetch(apiUrl);
    return await data.json();
  } catch (err) {
    console.log("Data not fetched", err);
  }
};
